<script setup lang="ts">
import {ref} from 'vue'
import {API_BASE} from '@/lib/api-base'
const token=new URLSearchParams(location.hash.slice(1)).get('token')||''
history.replaceState(null,'',location.pathname)
const password=ref(''),confirmation=ref(''),error=ref(''),done=ref(false),busy=ref(false)
async function save(){if(busy.value)return;error.value='';if(password.value!==confirmation.value){error.value='As senhas não coincidem.';return}busy.value=true;try{const r=await fetch(`${API_BASE}/auth/v1/reset-password`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,password:password.value,confirm_password:confirmation.value})});const d=await r.json();if(!r.ok)throw Error(d.msg||'Não foi possível alterar a senha.');password.value='';confirmation.value='';done.value=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><main class="reset-wrap"><section class="sq-card p-4"><h1 class="h4">Definir nova senha</h1><p v-if="done" class="alert alert-success" role="status">Senha alterada. Inicia sessão com a nova senha.</p><p v-else-if="!token" class="alert alert-warning">Ligação inválida. Pede uma nova recuperação.</p><form v-else @submit.prevent="save"><p>A ligação é válida durante 30 minutos e só pode ser utilizada uma vez.</p><label class="d-block mb-3">Nova senha<input v-model="password" type="password" autocomplete="new-password" minlength="8" maxlength="256" required class="form-control"></label><label class="d-block mb-3">Confirmar nova senha<input v-model="confirmation" type="password" autocomplete="new-password" minlength="8" maxlength="256" required class="form-control"></label><p v-if="error" class="alert alert-danger" role="alert">{{error}}</p><button class="btn btn-primary" :disabled="busy">{{busy?'A guardar…':'Guardar nova senha'}}</button></form><RouterLink class="d-block mt-3" to="/login">Voltar ao login</RouterLink><RouterLink v-if="!done" class="d-block mt-2" to="/recuperar-password">Pedir nova ligação</RouterLink></section></main></template>
<style scoped>.reset-wrap{min-height:100vh;display:grid;place-items:center;padding:1.5rem;background:var(--sq-bg)}.reset-wrap section{width:100%;max-width:480px}</style>
